  "offline.held.visit.cancelled": "ਤੁਹਾਡਾ ਕੰਮ ਭੇਜੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ECCS ਨੇ ਇਹ ਵਿਜ਼ਿਟ ਰੱਦ ਕਰ ਦਿੱਤੀ, ਇਸ ਲਈ ਕੰਮ ਭੇਜਿਆ ਨਹੀਂ ਗਿਆ। ਇਹ ਅਜੇ ਵੀ ਇਸ ਫੋਨ 'ਤੇ ਹੈ। ਕੁਝ ਵੀ ਮਿਟਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ECCS ਦਫ਼ਤਰ ਨੂੰ ਫੋਨ ਕਰੋ। ਇਸ ਫੋਨ 'ਤੇ ਰੱਖੇ ਹਨ: {count}",
  "offline.held.visit.gone": "ਇਹ ਵਿਜ਼ਿਟ ਹੁਣ ਤੁਹਾਡੀ ਨਹੀਂ ਰਹੀ: ਤੁਹਾਡਾ ਕੰਮ ਭੇਜੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਇਹ ਕਿਸੇ ਹੋਰ ਨੂੰ ਦੇ ਦਿੱਤੀ ਗਈ ਜਾਂ ਹਟਾ ਦਿੱਤੀ ਗਈ। ਤੁਹਾਡਾ ਕੰਮ ਅਜੇ ਵੀ ਇਸ ਫੋਨ 'ਤੇ ਹੈ। ECCS ਦਫ਼ਤਰ ਨੂੰ ਫੋਨ ਕਰੋ। ਜੇ ਉਹ ਵਿਜ਼ਿਟ ਤੁਹਾਨੂੰ ਵਾਪਸ ਦੇ ਦੇਣ, ਤਾਂ \"ਦੁਬਾਰਾ ਭੇਜੋ\" 'ਤੇ ਟੈਪ ਕਰੋ। ਇਸ ਫੋਨ 'ਤੇ ਰੱਖੇ ਹਨ: {count}",
  "offline.held.visit.finished": "ਇਹ ਵਿਜ਼ਿਟ ਪਹਿਲਾਂ ਹੀ ਕਿਸੇ ਹੋਰ ਫੋਨ ਤੋਂ ਜਾਂ ਦਫ਼ਤਰ ਵੱਲੋਂ ਪੂਰੀ ਕਰ ਦਿੱਤੀ ਗਈ ਸੀ, ਇਸ ਲਈ ਇਸ ਫੋਨ ਦਾ ਕੰਮ ਨਹੀਂ ਜੁੜਿਆ। ਇਹ ਅਜੇ ਵੀ ਇਸ ਫੋਨ 'ਤੇ ਹੈ। ਜੇ ਇਸਦੀ ਲੋੜ ਨਹੀਂ, ਤਾਂ ਇਸਨੂੰ ਇਸ ਫੋਨ ਤੋਂ ਮਿਟਾ ਦਿਓ। ਇਸ ਫੋਨ 'ਤੇ ਰੱਖੇ ਹਨ: {count}",
  "offline.held.inspection.cancelled": "ਤੁਹਾਡੇ ਜਵਾਬ ਭੇਜੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ECCS ਨੇ ਇਹ ਇੰਸਪੈਕਸ਼ਨ ਰੱਦ ਕਰ ਦਿੱਤੀ, ਇਸ ਲਈ ਜਵਾਬ ਭੇਜੇ ਨਹੀਂ ਗਏ। ਇਹ ਅਜੇ ਵੀ ਇਸ ਫੋਨ 'ਤੇ ਹਨ। ਕੁਝ ਵੀ ਮਿਟਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ECCS ਦਫ਼ਤਰ ਨੂੰ ਫੋਨ ਕਰੋ। ਇਸ ਫੋਨ 'ਤੇ ਰੱਖੇ ਹਨ: {count}",
