  "offline.held.inspection.finished": "ਇਹ ਇੰਸਪੈਕਸ਼ਨ ਪਹਿਲਾਂ ਹੀ ਕਿਸੇ ਹੋਰ ਫੋਨ ਤੋਂ ਜਾਂ ਦਫ਼ਤਰ ਵੱਲੋਂ ਪੂਰੀ ਕਰ ਦਿੱਤੀ ਗਈ ਸੀ, ਇਸ ਲਈ ਇਸ ਫੋਨ ਦੇ ਜਵਾਬ ਨਹੀਂ ਜੁੜੇ। ਇਹ ਅਜੇ ਵੀ ਇਸ ਫੋਨ 'ਤੇ ਹਨ। ਜੇ ਇਨ੍ਹਾਂ ਦੀ ਲੋੜ ਨਹੀਂ, ਤਾਂ ਇਨ੍ਹਾਂ ਨੂੰ ਇਸ ਫੋਨ ਤੋਂ ਮਿਟਾ ਦਿਓ। ਇਸ ਫੋਨ 'ਤੇ ਰੱਖੇ ਹਨ: {count}",
