  "plan.cancelConfirm": "{plan} ਪਲਾਨ ਰੱਦ ਕਰਨਾ ਹੈ?\n\nਤੁਹਾਡੀਆਂ ਵਿਜ਼ਿਟਾਂ {date} ਤੱਕ ਚੱਲਣਗੀਆਂ, ਜਦੋਂ ਉਹ ਸਾਈਕਲ ਮੁੱਕਦਾ ਹੈ ਜਿਸਦਾ ਇਨਵੌਇਸ ਪਹਿਲਾਂ ਹੀ ਬਣ ਚੁੱਕਾ ਹੈ।\n\n{date} ਤੋਂ ਬਾਅਦ ਪਲਾਨ ਰੀਨਿਊ ਨਹੀਂ ਹੋਵੇਗਾ, ਹੋਰ ਕੋਈ ਇਨਵੌਇਸ ਨਹੀਂ ਬਣੇਗਾ, ਅਤੇ ਉਸ ਦਿਨ ਤੋਂ ਬਾਅਦ ਦੀਆਂ ਵਿਜ਼ਿਟਾਂ ਤੁਹਾਡੇ ਕੈਲੰਡਰ ਵਿੱਚੋਂ ਹਟਾ ਦਿੱਤੀਆਂ ਜਾਣਗੀਆਂ।\n\nਤੁਸੀਂ {date} ਤੱਕ ਇਹ ਵਾਪਸ ਲੈ ਸਕਦੇ ਹੋ।",
  "plan.cancelConfirmNow": "{plan} ਪਲਾਨ ਰੱਦ ਕਰਨਾ ਹੈ?\n\nਇਹ ਅੱਜ ਹੀ ਮੁੱਕ ਜਾਵੇਗਾ। ਇਸਦੀਆਂ ਜਿਹੜੀਆਂ ਵਿਜ਼ਿਟਾਂ ਅਜੇ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋਈਆਂ, ਉਹ ਤੁਹਾਡੇ ਕੈਲੰਡਰ ਵਿੱਚੋਂ ਹਟਾ ਦਿੱਤੀਆਂ ਜਾਣਗੀਆਂ ਅਤੇ ਹੋਰ ਕੋਈ ਇਨਵੌਇਸ ਨਹੀਂ ਬਣੇਗਾ।\n\nਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ, ਪਰ ਤੁਸੀਂ ਦੁਬਾਰਾ ਪਲਾਨ ਲੈ ਸਕਦੇ ਹੋ।",
