  "push.channel.updates": "ਅੱਪਡੇਟ",
  "push.channel.updatesHelp": "ਵਿਜ਼ਿਟਾਂ, ਰਿਪੋਰਟਾਂ, ਇਸ਼ੂ ਅਤੇ ਲੌਗਇਨ, ਹੁੰਦੇ ਸਾਰ",
  "push.channel.reminders": "ਰਿਮਾਈਂਡਰ",
  "push.channel.remindersHelp": "ਸਮਾਂ ਲੰਘ ਚੁੱਕੀਆਂ ਚੈੱਕਲਿਸਟਾਂ, ਮਿਆਦ ਮੁੱਕਣ ਵਾਲੇ ਲਾਇਸੈਂਸ, ਆਉਣ ਵਾਲੀਆਂ ਵਿਜ਼ਿਟਾਂ",
  "push.ask.title": "ਤੁਰੰਤ ਪਤਾ ਲੱਗੇ?",
  "push.ask.body": "ਜਦੋਂ ਕਿਸੇ ਚੀਜ਼ ਵੱਲ ਤੁਹਾਡੇ ਧਿਆਨ ਦੀ ਲੋੜ ਹੋਵੇ, ECCS ਇਸ ਫੋਨ 'ਤੇ ਨੋਟੀਫਿਕੇਸ਼ਨ ਦਿਖਾ ਸਕਦਾ ਹੈ: ਵਿਜ਼ਿਟ ਪੂਰੀ ਹੋ ਗਈ, ECCS ਨੇ ਜਵਾਬ ਦਿੱਤਾ, ਚੈੱਕਲਿਸਟ ਦਾ ਸਮਾਂ ਲੰਘ ਗਿਆ, ਲਾਇਸੈਂਸ ਦੀ ਮਿਆਦ ਮੁੱਕਣ ਵਾਲੀ ਹੈ। ਦੇਖਣ ਲਈ ਤੁਹਾਨੂੰ ਵਾਰ-ਵਾਰ ਐਪ ਖੋਲ੍ਹਣੀ ਨਹੀਂ ਪਵੇਗੀ।",
  "push.ask.shared": "ਸਾਂਝੇ ਫੋਨ 'ਤੇ, ਇਹ ਸਿਰਫ਼ ਉਸੇ ਨੂੰ ਮਿਲਦੇ ਹਨ ਜਿਸ ਨੇ ਲੌਗਇਨ ਕੀਤਾ ਹੈ। ਲੌਕ ਕਰਨ ਤੋਂ ਬਾਅਦ ਕੋਈ ਨਹੀਂ ਦਿਖਦਾ।",
