  "face.consent.for": "{name} ਦੇ ਪੜ੍ਹਨ ਅਤੇ ਜਵਾਬ ਦੇਣ ਲਈ",
  "face.consent.intro": "ਇਹ ਆਪ ਪੜ੍ਹੋ, ਜਾਂ ਕਿਸੇ ਨੂੰ ਪੜ੍ਹ ਕੇ ਸੁਣਾਉਣ ਲਈ ਕਹੋ। ਫ਼ੈਸਲਾ ਤੁਹਾਡਾ ਹੈ।",
  "face.consent.who": "{employer} ਤੁਹਾਨੂੰ ਨੌਕਰੀ ਦੇਣ ਵਾਲਾ ਹੈ (ਤੁਸੀਂ ਇਨ੍ਹਾਂ ਕੋਲ ਨੌਕਰੀ ਕਰਦੇ ਹੋ) ਅਤੇ ਇਹੀ ਇਸਦੀ ਮੰਗ ਕਰ ਰਿਹਾ ਹੈ। ECCS, ਜੋ ਕੰਪਨੀ ਇਹ ਐਪ ਚਲਾਉਂਦੀ ਹੈ, {employer} ਵੱਲੋਂ ਇਹ ਜਾਣਕਾਰੀ ਰੱਖਦੀ ਹੈ।",
  "face.consent.why": "ਇਹ ਸਿਰਫ਼ ਇੱਕੋ ਕੰਮ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ: ਕਲਾਕ ਇਨ ਅਤੇ ਕਲਾਕ ਆਊਟ ਕਰਨ ਵੇਲੇ ਇਹ ਜਾਣਨ ਲਈ ਕਿ ਇਹ ਤੁਸੀਂ ਹੀ ਹੋ। ਤੁਹਾਡੀ ਤਨਖਾਹ ਦਾ ਹਿਸਾਬ ਉਨ੍ਹਾਂ ਸਮਿਆਂ ਤੋਂ ਲੱਗਦਾ ਹੈ।",
  "face.consent.not": "ਇਹ ਹੋਰ ਕਿਸੇ ਕੰਮ ਲਈ ਨਹੀਂ ਵਰਤਿਆ ਜਾਂਦਾ। ਇਹ ਵੇਚਿਆ ਨਹੀਂ ਜਾਂਦਾ, ਕਿਸੇ ਹੋਰ ਨੂੰ ਦਿੱਤਾ ਨਹੀਂ ਜਾਂਦਾ, ਅਤੇ ਇਸ਼ਤਿਹਾਰਾਂ ਲਈ ਨਹੀਂ ਵਰਤਿਆ ਜਾਂਦਾ।",
  "face.consent.choice": "ਤੁਸੀਂ ਨਾਂਹ ਕਰ ਸਕਦੇ ਹੋ। ਤੁਹਾਡੀ ਨੌਕਰੀ ਜਾਂ ਤੁਹਾਡੀ ਤਨਖਾਹ ਵਿੱਚ ਕੁਝ ਨਹੀਂ ਬਦਲਦਾ। ਇਸਦੀ ਥਾਂ ਮਾਲਕ ਜਾਂ ਮੈਨੇਜਰ ਤੁਹਾਡਾ ਕਲਾਕ ਇਨ ਅਤੇ ਕਲਾਕ ਆਊਟ ਕਰਨਗੇ।",
  "face.consent.withdraw": "ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਵੇਲੇ ਆਪਣਾ ਮਨ ਬਦਲ ਸਕਦੇ ਹੋ: ਮਾਲਕ ਨੂੰ ਦੱਸੋ, ਅਤੇ ਤੁਹਾਡੇ ਚਿਹਰੇ ਦਾ ਪੈਟਰਨ ਤੁਰੰਤ ਮਿਟਾ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਇਹ ਨੌਕਰੀ ਛੱਡਦੇ ਹੋ, ਉਦੋਂ ਵੀ ਇਹ ਮਿਟਾ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।",
  "face.consent.ask": "ਜੇ ਕੋਈ ਸਵਾਲ ਹੈ, ਤਾਂ ਮਾਲਕ ਨੂੰ ਪੁੱਛੋ।",
  "face.consent.under18": "ਜੇ ਤੁਹਾਡੀ ਉਮਰ 18 ਸਾਲ ਤੋਂ ਘੱਟ ਹੈ, ਤਾਂ \"ਮੈਂ ਸਹਿਮਤ ਨਹੀਂ ਹਾਂ\" ਚੁਣੋ।",
