  "face.consent.what": "ਹੁਣ ਤੁਹਾਡੇ ਚਿਹਰੇ ਦੀਆਂ ਕੁਝ ਫੋਟੋਆਂ ਖਿੱਚੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਤੋਂ ਚਿਹਰੇ ਦਾ ਪੈਟਰਨ (ਅੰਕਾਂ ਦੀ ਸੂਚੀ) ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ। ਇਹ ਫੋਟੋਆਂ ਰੱਖੀਆਂ ਨਹੀਂ ਜਾਂਦੀਆਂ। ਹਰ ਵਾਰ ਜਦੋਂ ਤੁਸੀਂ ਕਲਾਕ ਇਨ ਜਾਂ ਕਲਾਕ ਆਊਟ ਕਰਦੇ ਹੋ, ਇੱਕ ਫੋਟੋ ਖਿੱਚੀ ਜਾਂਦੀ ਹੈ। ਉਹ {days} ਦਿਨ ਰੱਖੀ ਜਾਂਦੀ ਹੈ ਤਾਂ ਜੋ ਮਾਲਕ ਅਤੇ ਮੈਨੇਜਰ ਉਸਨੂੰ ਜਾਂਚ ਸਕਣ, ਅਤੇ ਫਿਰ ਮਿਟਾ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ।",

