  "buddy.name": "ECCS Buddy",
  "buddy.button": "Buddy",
  "buddy.buttonLabel": "ECCS Buddy ਨੂੰ ਪੁੱਛੋ",
  "buddy.menu": "ECCS Buddy",
  "buddy.homeCard.title": "ECCS Buddy ਨੂੰ ਪੁੱਛੋ",
  "buddy.homeCard.body": "ਸਰਵਿਸ ਬੁੱਕ ਕਰੋ, ਚੈੱਕ ਜੋੜੋ, SOP ਲਿਖੋ, ਜਾਂ ਕੁਝ ਵੀ ਪੁੱਛੋ।",
  "buddy.welcome.title": "ਹੈਲੋ, ਮੈਂ ECCS Buddy ਹਾਂ",
  "buddy.welcome.body": "ਮੈਨੂੰ ਐਪ ਜਾਂ ਆਪਣੀ ਕਿਚਨ ਬਾਰੇ ਪੁੱਛੋ। ਮੈਂ ਤੁਹਾਡੇ ਅੱਜ ਦੇ ਕੰਮ ਦੇਖ ਸਕਦਾ ਹਾਂ ਅਤੇ ਤੁਹਾਡੇ ਲਈ ਬਦਲਾਅ ਤਿਆਰ ਕਰ ਸਕਦਾ ਹਾਂ।",
  "buddy.welcome.asksFirst": "ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਟੈਪ ਕਰਕੇ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰਦੇ, ਕੁਝ ਨਹੀਂ ਬਦਲੇਗਾ।",
  "buddy.welcome.more": "Buddy ਕੀ ਕਰ ਸਕਦਾ ਹੈ ਅਤੇ ਕੀ ਨਹੀਂ",
  "buddy.welcome.can": "ਐਪ ਵਿੱਚ ਕੰਮ ਕਿਵੇਂ ਕਰਨੇ ਹਨ, ਇਹ ਦੱਸਦਾ ਹੈ, ਅਤੇ ਫੂਡ ਸੇਫਟੀ, ਸਫ਼ਾਈ, ਕੀੜਿਆਂ ਤੇ ਚੂਹਿਆਂ ਅਤੇ ਕਿਚਨ ਚਲਾਉਣ ਬਾਰੇ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਦਿੰਦਾ ਹੈ।",
  "buddy.welcome.reads": "ਅੱਜ ਦੀਆਂ ਚੈੱਕਲਿਸਟਾਂ, ਵਿਜ਼ਿਟਾਂ, ਤੁਹਾਡਾ ਸਕੋਰ, ਲਾਇਸੈਂਸ, ਇਨਵੌਇਸ, ਪਲਾਨ, ਇਸ਼ੂ, ਇੰਸਪੈਕਸ਼ਨ, SOP, ਲੇਬਲ ਅਤੇ ਸਪਲਾਇਰ ਦੇਖ ਕੇ ਦੱਸਦਾ ਹੈ।",
  "buddy.welcome.changes": "ਤੁਹਾਡੇ ਟੈਪ ਲਈ ਤਿਆਰ ਕਰਦਾ ਹੈ: ਸਰਵਿਸ ਦੀ ਬੇਨਤੀ ਬੁੱਕ ਜਾਂ ਰੱਦ ਕਰਨਾ, ਚੈੱਕਲਿਸਟ ਆਈਟਮਾਂ ਅਤੇ ਚੈੱਕਲਿਸਟਾਂ, SOP, ਫੂਡ ਲੇਬਲ, ਅਤੇ ECCS ਨੂੰ ਮੈਸੇਜ।",
  "buddy.welcome.cannot": "ਕਦੇ ਭੁਗਤਾਨ ਨਹੀਂ ਕਰਦਾ, ਤੁਹਾਡਾ ਪਲਾਨ ਨਹੀਂ ਬਦਲਦਾ, ਦਸਤਾਵੇਜ਼ ਅੱਪਲੋਡ ਨਹੀਂ ਕਰਦਾ, ਅਤੇ ਸਟਾਫ ਦੀ ਹਾਜ਼ਰੀ, ਤਨਖਾਹ ਜਾਂ ਚਿਹਰੇ ਨਹੀਂ ਦੇਖਦਾ। ਇਹ ਸਕ੍ਰੀਨਾਂ ਤੁਹਾਡੇ ਲਈ ਖੋਲ੍ਹ ਦਿੰਦਾ ਹੈ।",
  "buddy.welcome.ai": "ਜਵਾਬ AI ਨੇ ਲਿਖੇ ਹਨ ਅਤੇ ਗਲਤ ਹੋ ਸਕਦੇ ਹਨ। ਚੈਟਾਂ {days} ਦਿਨ ਰੱਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।",
